package org.retrobridge.galaxyservices.s2;
import java.io.*;import java.net.*;import java.util.concurrent.*;import org.retrobridge.galaxyservices.Wire;
/** Loopback origin for old YouTube and its native media player, which can bypass Wi-Fi proxies. */
final class YouTubeLocal implements Runnable {
 final LegacyService service;volatile ServerSocket server;volatile boolean stopped;
 YouTubeLocal(LegacyService s){service=s;}
 public void run(){try{server=new ServerSocket();server.setReuseAddress(true);server.bind(new InetSocketAddress("127.0.0.1",8768));while(!stopped){final Socket c=server.accept();try{service.pool.execute(c,new Runnable(){public void run(){handle(c);}});}catch(RejectedExecutionException e){try{c.getOutputStream().write("HTTP/1.1 503 Service Unavailable\r\nConnection: close\r\nContent-Length: 0\r\n\r\n".getBytes("US-ASCII"));}catch(Exception ignored){}Wire.close(c);}}}catch(Exception e){if(!stopped)service.status("YouTube listener: "+e.getClass().getSimpleName());}}
 void handle(Socket c){try{c.setSoTimeout(15000);byte[] raw=Wire.header(c.getInputStream());String h=new String(raw,"ISO-8859-1");int end=h.indexOf("\r\n");String[] r=h.substring(0,end).split(" ");if(r.length!=3)throw new IOException("Request line");String path=r[1];if(path.startsWith("http://")){URI uri=new URI(path);if(!"127.0.0.1".equals(uri.getHost())||uri.getPort()!=8768)throw new IOException("Local origin only");path=uri.getRawPath()+(uri.getRawQuery()==null?"":"?"+uri.getRawQuery());}if(!path.startsWith("/")||path.startsWith("//"))throw new IOException("Origin path");android.util.Log.i("GalaxyYouTube",r[0]+" "+(path.indexOf('?')<0?path:path.substring(0,path.indexOf('?'))));if(!r[0].equals("GET")&&!r[0].equals("HEAD")&&path.startsWith("/feeds/api/")){YouTubeSecure.forward(service,c,r[0],path,h);return;}String modified=r[0]+" http://youtube.galaxy-services.invalid"+path+" "+r[2]+h.substring(end);service.forwardHeader(c,modified.getBytes("ISO-8859-1"));}catch(Exception e){android.util.Log.w("GalaxyYouTube",e.getClass().getSimpleName()+": "+e.getMessage());try{c.getOutputStream().write("HTTP/1.1 503 Service Unavailable\r\nConnection: close\r\nContent-Length: 0\r\n\r\n".getBytes("US-ASCII"));}catch(Exception ignored){}Wire.close(c);}}
 void close(){stopped=true;try{if(server!=null)server.close();}catch(Exception ignored){}}
}
